CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members(id text PRIMARY KEY,name text NOT NULL,interests jsonb NOT NULL DEFAULT '[]',preferences jsonb NOT NULL DEFAULT '{"theme":"default","textScale":100,"reducedMotion":false}',role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')),active boolean NOT NULL DEFAULT true,oidc_sub text UNIQUE);
CREATE TABLE sessions(token_hash text PRIMARY KEY,member_id text NOT NULL REFERENCES members(id),csrf_token text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE oidc_flows(id text PRIMARY KEY,state text NOT NULL,verifier text NOT NULL,nonce text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE tasks(id text PRIMARY KEY,title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 160),description text NOT NULL DEFAULT '',owner_id text NOT NULL REFERENCES members(id),creator_id text NOT NULL REFERENCES members(id),project text NOT NULL DEFAULT 'Produto',status text NOT NULL DEFAULT 'A fazer' CHECK(status IN ('A fazer','Fazendo','Em revisão','Feito','Cancelado')),priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Alta','Média','Baixa')),progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),due_date date,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status <> 'Feito' OR progress=100));
CREATE TABLE reports(id text PRIMARY KEY,task_id text NOT NULL REFERENCES tasks(id),author_id text NOT NULL REFERENCES members(id),previous_progress integer NOT NULL CHECK(previous_progress BETWEEN 0 AND 100),progress integer NOT NULL CHECK(progress BETWEEN 0 AND 100),narrative text NOT NULL CHECK(length(trim(narrative))>0),next_step text NOT NULL CHECK(length(trim(next_step))>0),reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publications(id text PRIMARY KEY,type text NOT NULL CHECK(type IN ('evento','oportunidade')),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 160),description text NOT NULL DEFAULT '',priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Alta','Média','Baixa')),starts_at timestamptz,ends_at timestamptz,deadline timestamptz,location text NOT NULL DEFAULT '',url text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Publicado' CHECK(status IN ('Publicado','Cancelado','Encerrado')),author_id text NOT NULL REFERENCES members(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at IS NULL OR (starts_at IS NOT NULL AND ends_at>=starts_at)));
CREATE TABLE comments(id text PRIMARY KEY,task_id text REFERENCES tasks(id),publication_id text REFERENCES publications(id),author_id text NOT NULL REFERENCES members(id),text text NOT NULL CHECK(length(trim(text))>0),priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Alta','Média','Baixa')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK((task_id IS NOT NULL)::integer+(publication_id IS NOT NULL)::integer=1));
CREATE TABLE comment_mentions(comment_id text NOT NULL REFERENCES comments(id),member_id text NOT NULL REFERENCES members(id),PRIMARY KEY(comment_id,member_id));
CREATE TABLE help_requests(id text PRIMARY KEY,task_id text NOT NULL REFERENCES tasks(id),author_id text NOT NULL REFERENCES members(id),text text NOT NULL CHECK(length(trim(text))>0),priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Alta','Média','Baixa')),status text NOT NULL DEFAULT 'Aberto' CHECK(status IN ('Aberto','Em atendimento','Resolvido','Cancelado')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE help_recipients(help_id text NOT NULL REFERENCES help_requests(id),member_id text NOT NULL REFERENCES members(id),state text NOT NULL DEFAULT 'Pendente',PRIMARY KEY(help_id,member_id));
CREATE TABLE notifications(id text PRIMARY KEY,member_id text NOT NULL REFERENCES members(id),type text NOT NULL CHECK(type IN ('help','mention','event','reminder')),title text NOT NULL,body text NOT NULL DEFAULT '',task_id text REFERENCES tasks(id),publication_id text REFERENCES publications(id),help_id text REFERENCES help_requests(id),dedupe_key text NOT NULL UNIQUE,read_at timestamptz,confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id text PRIMARY KEY,title text NOT NULL,body text NOT NULL,state text NOT NULL DEFAULT 'Validação pendente',file_name text NOT NULL,hash text NOT NULL,author_id text NOT NULL REFERENCES members(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(file_name,hash));
CREATE TABLE audit_log(id text PRIMARY KEY,actor_id text NOT NULL REFERENCES members(id),action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(member_id text NOT NULL REFERENCES members(id),key text NOT NULL,route text NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(member_id,key));
CREATE INDEX tasks_owner_idx ON tasks(owner_id,status);
CREATE INDEX reports_task_time_idx ON reports(task_id,created_at DESC);
CREATE INDEX notifications_member_idx ON notifications(member_id,created_at DESC);
CREATE INDEX comments_task_idx ON comments(task_id,created_at);
INSERT INTO schema_migrations(version) VALUES(1);
